/**
 * Split a container entrypoint like `docker/Dockerfile#worker` into the
 * Dockerfile path and the stage to build. Only a `#` in the last path segment
 * starts a stage, so `#` in a directory name stays part of the path.
 * `buildTarget` is `undefined` when the entrypoint names no stage.
 */
export declare function splitDockerfileEntrypoint(entrypoint: string): {
    path: string;
    buildTarget?: string;
};
/** Whether `stage` is a valid Dockerfile stage name to build. */
export declare function isValidDockerfileStage(stage: string): boolean;
/** User-facing rule for a valid stage, to append to error messages. */
export declare const DOCKERFILE_STAGE_HINT = "A stage after `#` must start with a lowercase letter and contain only lowercase letters, digits, `.`, `_` and `-`, up to 256 characters.";
